function validate([celsius]) {
  if (typeof celsius !== 'number' || !Number.isFinite(celsius)) return 'celsius must be a number.';
  if (celsius < 0 || celsius > 1000) return 'celsius is between 0 and 1000.';
  if (Math.abs(Math.round(celsius * 100) - celsius * 100) > 1e-6) return 'celsius has at most two decimal places.';
  return null;
}

