function convertTemperature(celsius) {
  // Work in hundredths of a degree, then scale back, so the formulas are written another way.
  const hundredths = Math.round(celsius * 100);
  return [(hundredths + 27315) / 100, (hundredths * 9) / 500 + 32];
}

